(function(){
  function task(task){var errors=[];if(!task.title.trim())errors.push("Describe la actividad.");if(!task.modeIds.length)errors.push("Relaciona la tarea con al menos un modo.");if(!task.frequency.trim())errors.push("Indica una frecuencia o disparador.");if(!task.foundation.trim())errors.push("Justifica el intervalo o disparador.");if(!task.acceptanceCriterion.trim())errors.push("Define un criterio de aceptación.");return{valid:!errors.length,errors:errors};}
  function decision(decision){var errors=[];if(!decision.modeId)errors.push("Selecciona un modo.");if(!decision.type)errors.push("Selecciona una decisión.");if(!String(decision.justification||"").trim())errors.push("Justifica la decisión sin tarea.");return{valid:!errors.length,errors:errors};}
  function all(state){var errors=[];state.proposedTasks.forEach(function(t){task(t).errors.forEach(function(x){errors.push(t.id+": "+x);});});state.noTaskDecisions.forEach(function(d){decision(d).errors.forEach(function(x){errors.push(d.id+": "+x);});});var covered={};state.proposedTasks.forEach(function(t){t.modeIds.forEach(function(id){covered[id]=true;});});state.noTaskDecisions.forEach(function(d){covered[d.modeId]=true;});state.functions.forEach(function(fn){fn.functionalFailures.forEach(function(ff){ff.failureModes.forEach(function(m){if(!covered[m.id])errors.push(m.id+": vincula una tarea o una decisión explícita sin tarea.");});});});return{valid:!errors.length,errors:errors};}
  window.CMMS_TREATMENT_VALIDATIONS={task:task,decision:decision,all:all};
})();
